"""State-local data declarations and change records."""

from copy import deepcopy
from dataclasses import dataclass
from typing import Any

from .exceptions import InvalidDefinition


_UNSET = object()


class DataVar:
    """Declare a state variable with an optional type and factory."""

    def __init__(self, default=_UNSET, *, factory=None, type=None):
        if default is not _UNSET and factory is not None:
            raise InvalidDefinition("DataVar cannot specify both default and factory")
        if factory is not None and not callable(factory):
            raise InvalidDefinition("DataVar factory must be callable")
        self.default = default
        self.factory = factory
        self.type = type

    def make_value(self):
        value = self.factory() if self.factory is not None else (
            None if self.default is _UNSET else deepcopy(self.default)
        )
        self.validate(value)
        return value

    def validate(self, value):
        if self.type is not None and not isinstance(value, self.type):
            raise InvalidDefinition(f"Expected {self.type!r}, got {type(value)!r}")


@dataclass(frozen=True)
class DataChangeInfo:
    state_id: str
    key: str
    old_value: Any
    new_value: Any

    _callbacks: Any = None,
    data: Any = None,
):
    if data is not None and (not isinstance(data, dict) or any(not isinstance(k, str) for k in data)):
        raise InvalidDefinition("State data must be a dict with string keys")
    self.data = dict(data) if data is not None else {}
    self.name = name

self._state_data: Dict[str, dict] = {}
self._history_data: Dict[str, dict] = {}
self._data_changes: List[DataChangeInfo] = []
self.model: TModel = model if model is not None else Model()  # type: ignore[assignment]

def _resolve_data_state(self, state):
    if isinstance(state, str):
        return next((s for s in self.states_map.values() if s.id == state), None)
    return next((s for s in self.states_map.values() if s is state or getattr(state, "_state", None) is s), None)

def get_state_data(self, state):
    state = self._resolve_data_state(state)
    return self._state_data.get(state.id) if state is not None else None

@property
def state_data_values(self):
    return deepcopy(self._state_data)

def set_state_data(self, state, key, value):
    state = self._resolve_data_state(state)
    if state is None or state.id not in self._state_data:
        raise InvalidDefinition("State is not active")
    if key not in state.data:
        raise InvalidDefinition(f"Undeclared state data key: {key!r}")
    declaration = state.data[key]
    if isinstance(declaration, DataVar):
        declaration.validate(value)
    data = self._state_data[state.id]
    old = deepcopy(data[key])
    data[key] = value
    self._data_changes.append(DataChangeInfo(state.id, key, old, deepcopy(value)))

def get_data_changes(self):
    return list(self._data_changes)

def _enter_state_data(self, state, restored=None):
    if restored is not None and state.id in restored:
        self._state_data[state.id] = deepcopy(restored[state.id])
        return
    self._state_data[state.id] = {
        key: (value.make_value() if isinstance(value, DataVar) else
              value() if callable(value) else deepcopy(value))
        for key, value in state.data.items()
    }

def _scoped_state_data(self, state):
    result = {}
    for item in reversed([state, *state.ancestors()]):
        result.update(self._state_data.get(item.id, {}))
    return result

